/** Suggested moves [{ districtKey, toRegionId }] for Germany. */
export function suggestedMoves() {
  return Object.entries(REGION_SUGGESTION).flatMap(([toRegionId, names]) =>
    names.map((name) => ({ districtKey: `DE|${name}`, toRegionId }))
  );
}
